        let payload = std::panic::catch_unwind(std::panic::AssertUnwindSafe(action)).unwrap_err();
        payload
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| {
                payload
                    .downcast_ref::<&str>()
                    .map(|value| (*value).to_owned())
            })
            .unwrap()
    };
    for (input, mode, normalized) in [
        ("hw:0\0suffix", AlsaAccessMode::Shared, "plughw:0\0suffix"),
